# Compare per sheet: find cells that differ in value
for sheet_name in wb_in.sheetnames:
    ws_in = wb_in[sheet_name]
    ws_golden = wb_golden[sheet_name]
    diff_count = 0
    for row in range(1, ws_in.max_row + 1):
        for col in range(1, ws_in.max_column + 1):
            cell_in = ws_in.cell(row=row, column=col)
            cell_golden = ws_golden.cell(row=row, column=col)
            val_in = cell_in.value
            val_golden = cell_golden.value
            if val_in != val_golden:
                # Skip if both are None or empty
                if val_in is None and val_golden is None:
                    continue
                if val_in is None and val_golden == '':
                    continue
                if val_in == '' and val_golden is None:
                    continue
                diff_count += 1
                if diff_count <= 10:
                    print(f'{sheet_name} {cell_in.coordinate}: input={repr(val_in)[:80]} vs golden={repr(val_golden)[:80]}')
    if diff_count > 0:
        print(f'{sheet_name}: {diff_count} differences total')
