cd /tmp && python3 -c "
import openpyxl
wb_in = openpyxl.load_workbook('/tmp/llm_rollout_n1zmhyh2/151_034_native_004%2F3.360495.HY0ZKT2WOOXY42LELOSQSBI0SSCA13CJA.1_template_3417_input.xlsx', data_only=False)
wb_golden = openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_enron_batch1/passed/template/151_034_native_004%2F3.360495.HY0ZKT2WOOXY42LELOSQSBI0SSCA13CJA.1_template_3417_golden.xlsx', data_only=False)

# More comprehensive style comparison: fill patternType + fgColor rgb + bgColor rgb, font name/size/bold/color, border style
def fill_key(f):
    try:
        return (f.patternType, f.fgColor.rgb, f.bgColor.rgb)
    except Exception:
        return None
def font_key(f):
    try:
        return (f.name, f.size, f.bold, f.italic, f.color.rgb if f.color else None)
    except Exception:
        return None
def border_key(b):
    try:
        return (b.left.style, b.right.style, b.top.style, b.bottom.style)
    except Exception:
        return None

diffs = 0
for sheet_name in wb_in.sheetnames:
    ws_in = wb_in[sheet_name]
    ws_golden = wb_golden[sheet_name]
    for row in range(1, max(ws_in.max_row, ws_golden.max_row) + 1):
        for col in range(1, max(ws_in.max_column, ws_golden.max_column) + 1):
            c_in = ws_in.cell(row=row, column=col)
            c_gd = ws_golden.cell(row=row, column=col)
            if fill_key(c_in.fill) != fill_key(c_gd.fill):
                diffs += 1
                if diffs <= 10:
                    print(f'FILL {sheet_name} {c_in.coordinate}: in={fill_key(c_in.fill)!r} gd={fill_key(c_gd.fill)!r}')
            if font_key(c_in.font) != font_key(c_gd.font):
                diffs += 1
                if diffs <= 10:
                    print(f'FONT {sheet_name} {c_in.coordinate}: in={font_key(c_in.font)!r} gd={font_key(c_gd.font)!r}')
            if border_key(c_in.border) != border_key(c_gd.border):
                diffs += 1
                if diffs <= 10:
                    print(f'BORDER {sheet_name} {c_in.coordinate}: in={border_key(c_in.border)!r} gd={border_key(c_gd.border)!r}')
print('Style diffs:', diffs)
"
